import {CaptureTimeline,VisualTimeline,MAX_SECONDS,encodePerformance,decodePerformance,wavFile,clone} from './recorder-core.js?rev=recorder-20';
import {PerformanceAudio} from './recorder-audio.js?rev=recorder-20';
import {PerformanceStore,takeSummary} from './performance-store.js?rev=recorder-20';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
export function createRecorderController(bridge,{store=new PerformanceStore(),makeAudio=(audio,callbacks)=>new PerformanceAudio(audio,callbacks)}={}){
 let phase='idle',timeline=null,selected=null,draft=null,items=[],playback=null,playStart=0,playLoop=true,backup=null,closing=false,lastDeadline=-1,lastSettings='',lastGesture=-1,error='',ticket=0;
 const audio=bridge.audio,backend=makeAudio(audio,{onCut:end=>cut(end),onDone:result=>complete(result)});
 const busy=()=>phase!=='idle';
 function status(message){$('recorderStatus').textContent=message;$('recordBarStatus').textContent=message;}
 function sync(){const active=busy();document.body.classList.toggle('performance-playback',phase==='playing');document.body.classList.toggle('performance-finishing',['preparing','finalizing'].includes(phase));$('recordBar').hidden=!active;$('recordStart').disabled=active;$('recordMode').disabled=active;$('recordCycles').disabled=active||$('recordMode').value==='manual';$('recordFinish').disabled=phase!=='recording';$('recordCancel').disabled=!['recording','preparing','finalizing'].includes(phase);$('recordBarStop').textContent=phase==='recording'?'Finish at next bar':phase==='playing'?'Stop playback':'Cancel';$('start').disabled=active;for(const id of ['takePlay','takeOnce','takeLoad','takeDownload','takeWav','takeDelete','takeRename','takeSeam','takeSelect'])$(id).disabled=active||!selected;$('takeImport').disabled=active;$('takeStop').disabled=phase!=='playing';$('recordLauncher').classList.toggle('is-recording',phase==='recording');$('recordLauncher').textContent=phase==='recording'?'● Recording':phase==='playing'?'↻ Loop playing':'Record / Library';}
 function details(){if(!selected){$('takeInfo').textContent='Your performances stay in this browser. Import a file to bring one back.';return;}$('takeInfo').textContent=`${time(selected.frames/selected.sampleRate)} · ${selected.sampleRate/1000} kHz stereo · ${selected.events.length} visual & setting events${draft?.id===selected.id?' · not yet saved in browser':''}`;$('takeName').value=selected.name;$('takeSeam').value=selected.seamMs;$('takeSeamValue').textContent=selected.seamMs+' ms';}
 async function refresh(){try{items=await store.list();}catch(e){error=e.message;items=[];}if(draft&&!items.some(t=>t.id===draft.id))items.unshift(takeSummary(draft));$('takeSelect').innerHTML=items.length?items.map(t=>`<option value="${esc(t.id)}">${esc(t.name)} · ${time(t.frames/t.sampleRate)}</option>`).join(''):'<option value="">No performances yet</option>';if(selected)$('takeSelect').value=selected.id;else if(items[0])await choose(items[0].id);details();sync();if(error&&!busy())status(error);}
 async function choose(id){selected=draft?.id===id?draft:await store.get(id);if(!selected)throw new Error('That take is no longer available.');bridge.validate(selected);details();sync();}
 async function keep(take){selected=take;draft=take;error='';try{await store.put(take);draft=null;}catch(e){error=e.message;}await refresh();return !draft;}
 function fail(e){error=e.message||'The performance could not be completed.';status(error);sync();}
 async function record(){if(busy())return;const ownTicket=++ticket;phase='preparing';status('Preparing the recorder and instruments…');sync();try{await backend.prepare();await bridge.prepareLive();if(ownTicket!==ticket)return;const snapshot=bridge.snapshot(),cycleBeats=Number(snapshot.main.settings.chordLength)*4,cycles=Math.max(1,Math.min(16,Math.round(Number($('recordCycles').value))||1)),manual=$('recordMode').value==='manual';$('recordCycles').value=String(cycles);if(!manual&&cycleBeats*cycles*60/snapshot.main.bpm>MAX_SECONDS)throw new Error('That take would exceed 10 minutes. Choose fewer cycles, shorter chords or a faster tempo.');const start=Math.round((audio.ctx.currentTime+.16)*audio.ctx.sampleRate)/audio.ctx.sampleRate;await bridge.beginLive(start);timeline=new CaptureTimeline({start,bpm:audio.bpm,cycleBeats,cycles,manual,snapshot:bridge.snapshot(),scene:bridge.scene(),name:$('recordName').value.trim()||'Performance '+new Date().toLocaleString()});phase='recording';closing=false;lastGesture=-1;lastSettings=JSON.stringify(timeline.snapshot);const end=timeline.deadline(start);audio.recordingEnd=end;lastDeadline=end;backend.begin(start,end);$('recordDialog').close();status(manual?'Recording · finish on a bar when ready':'Recording · '+cycles+' progression '+(cycles===1?'cycle':'cycles'));sync();}catch(e){if(ownTicket!==ticket)return;phase='idle';backend.cancel();bridge.stopLive();fail(e);}}
 function stateChanged(){if(phase!=='recording')return;const now=audio.ctx.currentTime,snapshot=bridge.snapshot();timeline.tempo(now,snapshot.main.bpm);const json=JSON.stringify(snapshot);if(json!==lastSettings){lastSettings=json;capture('settings',snapshot,now);}frame();}
 function capture(kind,data,at=audio.ctx?.currentTime){if(phase!=='recording'||!Number.isFinite(at))return;if(kind==='gesture'){if(!data.ended&&at-lastGesture<.05)return;lastGesture=at;}timeline.add(kind,data,at);if(timeline.limit)finish();}
 function finish(){if(phase!=='recording'||closing)return;closing=true;const end=timeline.finishOnBar(audio.ctx.currentTime);audio.recordingEnd=end;backend.end(end);bridge.trimFuture?.(end);lastDeadline=end;status('Finishing at the next bar…');sync();}
 function cut(end){if(phase!=='recording')return;timeline.advance(end);phase='finalizing';audio.recordingEnd=end;bridge.freezeLive(end);status('Finishing the effect tail and saving…');sync();}
 async function complete({end,channels}){if(!['recording','finalizing'].includes(phase))return;const ownTicket=ticket;try{if(phase==='recording')cut(end);const take=timeline.finish(end,audio.ctx.sampleRate,channels);bridge.stopLive();audio.recordingEnd=null;phase='idle';timeline=null;const saved=await keep(take);if(ownTicket!==ticket)return;status(saved?'Saved in this browser. Your take is ready.':error);sync();if($('recordAutoLoop').checked)await play(true);else $('recordDialog').showModal();}catch(e){phase='idle';audio.recordingEnd=null;bridge.stopLive();fail(e);}}
 function cancel(){ticket++;backend.cancel();backend.stop();timeline=null;audio.recordingEnd=null;bridge.stopLive();phase='idle';closing=false;status('Recording cancelled. Earlier saved performances are still available.');sync();}
 async function play(loop=true){if(busy()||!selected)return;phase='preparing';sync();status('Preparing playback…');const ownTicket=++ticket;try{bridge.validate(selected);backup={snapshot:bridge.snapshot(),scene:bridge.scene()};bridge.stopLive();bridge.applySnapshot(selected.snapshot);bridge.restoreScene(selected.scene);playLoop=loop;playback=new VisualTimeline(selected,(event,t)=>bridge.applyEvent(event,playStart+t),snapshot=>bridge.applySnapshot(snapshot));const start=await backend.play(selected,{loop,onEnded:()=>stopPlayback()});if(ownTicket!==ticket||start===null)return;playStart=start;phase='playing';bridge.playbackStarted?.();status(loop?'Loop playing · '+selected.name:'Playing once · '+selected.name);sync();$('recordDialog').close();}catch(e){if(ownTicket!==ticket)return;phase='idle';backend.stop();if(backup)bridge.applySnapshot(backup.snapshot);fail(e);}}
 function stopPlayback(){ticket++;backend.stop();playback=null;phase='idle';if(backup){bridge.applySnapshot(backup.snapshot);backup=null;}bridge.exitPlayback();status('Playback stopped. Your live setup is ready.');sync();}
 function frame(){if(phase==='recording'){
  const now=audio.ctx.currentTime;if(now<timeline.start)return;const end=timeline.deadline(now);audio.recordingEnd=end;if(Math.abs(end-lastDeadline)>1/audio.ctx.sampleRate){backend.end(end);bridge.trimFuture?.(end);lastDeadline=end;}
  const elapsed=Math.max(0,now-timeline.start),total=end-timeline.start;$('recordProgress').value=Math.min(1,elapsed/total);$('recordBarTime').textContent=time(elapsed)+' / '+(timeline.manual&&!closing?'manual':time(total));if(!closing)status(`Recording · ${time(elapsed)} · ${(timeline.beats/timeline.cycleBeats).toFixed(1)}${timeline.manual?'':' / '+Number($('recordCycles').value)} cycles`);
 }else if(phase==='playing'&&audio.ctx.currentTime>=playStart){const elapsed=audio.ctx.currentTime-playStart,{cycle,position}=playback.frame(elapsed,playLoop),duration=selected.frames/selected.sampleRate;$('recordProgress').value=position/duration;$('recordBarTime').textContent=`${playLoop?'Loop '+(cycle+1)+' · ':''}${time(position)} / ${time(duration)}`;}}
 function download(blob,suffix){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=(selected.name.replace(/[^\p{L}\p{N} _-]/gu,'').trim()||'Chromaflow-performance')+suffix;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const run=fn=>async()=>{try{await fn();}catch(e){fail(e);}};
 $('recordLauncher').onclick=()=>{$('recordDialog').showModal();refresh().catch(fail);};$('closeRecorder').onclick=()=>$('recordDialog').close();$('recordStart').onclick=record;$('recordFinish').onclick=finish;$('recordCancel').onclick=()=>phase==='playing'?stopPlayback():cancel();$('recordBarStop').onclick=()=>phase==='playing'?stopPlayback():phase==='recording'?finish():cancel();$('recordMode').addEventListener('change',sync);
 $('takeSelect').addEventListener('change',run(()=>choose($('takeSelect').value)));$('takePlay').onclick=()=>play(true);$('takeOnce').onclick=()=>play(false);$('takeStop').onclick=stopPlayback;
 $('takeLoad').onclick=run(async()=>{if(!selected||busy())return;bridge.validate(selected);bridge.stopLive();bridge.applySnapshot(selected.snapshot,true);bridge.restoreScene(selected.scene);status('Opening setup loaded. Press Begin listening to perform with it.');});
 $('takeRename').onclick=run(async()=>{if(!selected||busy())return;selected.name=$('takeName').value.trim().slice(0,80)||'Untitled performance';await keep(selected);status(draft?error:'Performance renamed.');});
 $('takeSeam').addEventListener('change',run(async()=>{if(!selected||busy())return;selected.seamMs=Number($('takeSeam').value);await keep(selected);details();}));$('takeSeam').addEventListener('input',()=>{$('takeSeamValue').textContent=$('takeSeam').value+' ms';});
 $('takeDownload').onclick=run(()=>download(encodePerformance(selected),'.chromaflow'));$('takeWav').onclick=run(()=>download(wavFile(selected),'.wav'));
 $('takeDelete').onclick=run(async()=>{if(!selected||busy())return;const id=selected.id;if(draft?.id===id)draft=null;else await store.remove(id);selected=null;await refresh();status('Performance deleted from this browser.');});
 $('takeImport').onclick=()=>$('takeFile').click();$('takeFile').addEventListener('change',run(async()=>{const file=$('takeFile').files?.[0];$('takeFile').value='';if(!file||busy())return;const take=await decodePerformance(file);bridge.validate(take);take.id=globalThis.crypto?.randomUUID?.()||'import-'+Date.now();take.created=new Date().toISOString();await keep(take);status(draft?error:'Performance imported and saved in this browser.');}));
 sync();refresh().catch(fail);
 return {frame,stateChanged,capture,get recording(){return phase==='recording';},get replaying(){return phase==='playing';},get arming(){return phase==='recording'&&audio.ctx.currentTime<timeline.start;},get blocked(){return ['preparing','finalizing','playing'].includes(phase)||(phase==='recording'&&audio.ctx.currentTime<timeline.start);},get phase(){return phase;},finish,stopPlayback,cancel};
}
